+        let r = p.step(rec(&chunk(json!([{"index":0}]))), &v);
+        assert!(matches!(r, Err(StepError::Deviation("choice_without_delta"))));
+    }
+
+    #[test]
+    fn a_choice_without_delta_at_position_1_also_deviates() {
+        let mut p = OpenAiStream::default();
+        let v = Verdicts::new();
+        start_call(&mut p, &v);
