+    }
+
+    /// Review Focus 1: a bare finish record is what a real stream ends with.
+    #[test]
+    fn a_finish_record_without_delta_is_conforming() {
+        let mut p = OpenAiStream::default();
+        let v = Verdicts::new();
+        start_call(&mut p, &v);
