+    /// Spec § 5.2: `"delta": null` stays `Malformed("delta")` in every position (SMA-749 classifier).
+    #[test]
+    fn a_null_delta_inside_an_open_call_is_a_stream_failure() {
+        let mut p = OpenAiStream::default();
+        let v = Verdicts::new();
