+        let mut i = crate::interceptor::Interceptor::new(crate::Format::OpenAiChat, crate::Limits::defaults(), Bytes::from_static(b"data: [DONE]\n\n"), std::time::Instant::now());
+        let t0 = std::time::Instant::now();
