111	/// Whether a model call's arguments match a decided call's. The decider sees `{}` for empty
112	/// function arguments (the core's rule), so a client's raw `""` matches it. A `parsed` model value
113	/// is compared with the parsed decided string. The match is exact, also for the snapshot at an
114	/// excused raise: a prefix of allowed arguments can be a call that an argument-reading policy
115	/// (SMA-752) denies, and the gateway never asks the decider about it.
116	fn arguments_match(mc: &ModelCall, decided: &ModelCall) -> bool {
117	    if mc.kind == "other" {
118	        return true; // the decided form of kind Other is the raw entry
119	    }
120	    if mc.parsed {
121	        let full = if decided.arguments.is_empty() {
122	            Ok(json!({}))
123	        } else {
124	            serde_json::from_str::<Value>(&decided.arguments)
125	        };
126	        let (Ok(full), Ok(got)) = (full, serde_json::from_str::<Value>(&mc.arguments)) else {
127	            return false;
128	        };
129	        return got == full;
130	    }
131	    mc.arguments == decided.arguments || (mc.arguments.is_empty() && decided.arguments == "{}")
132	}
