134	/// Invariant I1 as property P1 states it (spec § 2, § 8.1). Every call a client model derives from
135	/// `out` matches a distinct call the decider allowed, by choice, kind, name and arguments
136	/// (arguments are not compared for kind `other`, whose decided form is the raw entry).
137	///
138	/// A model that raises on `out` is an error unless the interceptor dropped a record or took an
139	/// `on_failure` path (`core_failed`), or the client already raises on the upstream bytes `input`:
140	/// a correct interceptor must not make a working client fail. An excused raise is still checked:
141	/// the client may have acted on calls before it raised, so every call in its snapshot must match
142	/// a decided, allowed call exactly. A strict prefix of an allowed call is never accepted: the
143	/// gateway never asked the decider about it, and an argument-reading policy (SMA-752) may deny it.
144	pub fn check_i1(format: Format, input: &[u8], out: &[u8], decided: &[(ToolCall, Decision)], core_failed: bool) -> Result<(), String> {
145	    let allowed: Vec<ModelCall> = decided.iter().filter(|(_, d)| d.is_allow()).map(|(c, _)| as_model_call(c)).collect();
146	    let show = || String::from_utf8_lossy(out).into_owned();
147	    for (model, run) in runners(format) {
148	        let r = run(out);
149	        match &r.error {
150	            Some(_) if core_failed || run(input).error.is_some() => {} // excused; the snapshot is still checked
151	            Some(e) => return Err(format!("{model} raised on the output: {e}\n{}", show())),
152	            None => {}
153	        }
154	        let mut left = allowed.clone();
155	        for mc in r.calls {
156	            let hit = left.iter().position(|a| a.choice == mc.choice && a.kind == mc.kind && a.name == mc.name && arguments_match(&mc, a));
157	            match hit {
158	                Some(i) => {
159	                    left.remove(i);
160	                }
161	                None => return Err(format!("{model} runs an undecided or blocked call {mc:?}\nallowed: {allowed:?}\n{}", show())),
162	            }
163	        }
164	    }
165	    Ok(())
166	}
