349	/// JavaScript `String(v)` for a JSON value, enough for `+=` on an argument string.
350	fn js_string(v: &Value) -> String {
351	    match v {
352	        Value::String(s) => s.clone(),
353	        Value::Null => "null".into(),
354	        Value::Object(_) => "[object Object]".into(),
