359	/// A safe-integer index in `0..max`, as `Number.isSafeInteger(i) && i >= 0 && i < max`.
360	fn js_index(v: Option<&Value>, max: u64) -> Option<u64> {
361	    let n = v?.as_number()?;
362	    let i = n.as_u64().or_else(|| n.as_f64().filter(|f| f.fract() == 0.0 && *f >= 0.0).map(|f| f as u64))?;
