379	            if sse.data == "[DONE]" {
380	                break;
381	            }
382	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("SyntaxError: {e}"))?;
383	            if sse.event.as_deref() == Some("error") || js_truthy(v.get("error")) {
384	                return Err("APIError: error record".into());
385	            }
386	            let Some(Value::Array(cs)) = v.get("choices") else {
387	                return Err("TypeError: chunk.choices is not iterable".into());
388	            };
389	            for c in cs {
390	                let idx = js_index(c.get("index"), 128).ok_or("OpenAIError: invalid choice index")?;
391	                let ch = choices.entry(idx).or_default();
392	                if js_truthy(c.get("finish_reason")) {
393	                    ch.finish = c.get("finish_reason").cloned();
394	                }
395	                let Some(d) = c.get("delta").filter(|d| js_truthy(Some(d))) else { continue };
396	                if js_truthy(d.get("role")) {
397	                    ch.role = d.get("role").cloned();
398	                }
399	                if let Some(f) = d.get("function_call").filter(|f| js_truthy(Some(f))) {
400	                    match &mut ch.function_call {
401	                        Some(s) => {
402	                            if js_truthy(f.get("name")) {
403	                                s.insert("name".into(), f["name"].clone());
404	                            }
405	                            if js_truthy(f.get("arguments")) {
406	                                let prev = s.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default();
407	                                s.insert("arguments".into(), Value::String(prev + &js_string(&f["arguments"])));
408	                            }
409	                        }
410	                        None => ch.function_call = Some(f.as_object().cloned().unwrap_or_default()),
411	                    }
412	                }
413	                let Some(tcs) = d.get("tool_calls").filter(|t| js_truthy(Some(t))) else { continue };
414	                let Value::Array(tcs) = tcs else { return Err("TypeError: tool_calls is not iterable".into()) };
415	                for e in tcs {
416	                    let i = js_index(e.get("index"), 128).ok_or("OpenAIError: invalid tool call index")?;
417	                    let t = ch.tools.entry(i).or_default();
418	                    if js_truthy(e.get("id")) {
419	                        t.id = e.get("id").cloned();
420	                    }
421	                    if js_truthy(e.get("type")) {
422	                        t.ty = e.get("type").cloned();
423	                    }
424	                    if let Some(cu) = e.get("custom").filter(|x| js_truthy(Some(x))) {
425	                        let s = t.custom.get_or_insert_with(|| (cu.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
426	                        if js_truthy(cu.get("name")) {
427	                            s.0 = cu["name"].clone();
428	                        }
429	                        if js_truthy(cu.get("input")) {
430	                            s.1.push_str(&js_string(&cu["input"]));
431	                        }
432	                    }
433	                    if let Some(f) = e.get("function").filter(|x| js_truthy(Some(x))) {
434	                        let s = t.function.get_or_insert_with(|| (f.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
435	                        if js_truthy(f.get("name")) {
436	                            s.0 = f["name"].clone();
437	                        }
438	                        if let Some(a) = f.get("arguments").filter(|a| !a.is_null()) {
439	                            s.1.push_str(&js_string(a));
440	                        }
441	                    }
442	                }
443	            }
444	        }
445	        Ok(())
446	    };
447	    let mut error = step().err();
448	    let mut calls = Vec::new();
449	    for (idx, ch) in &choices {
450	        let choice = u32::try_from(*idx).expect("below 128");
451	        if error.is_none() && ch.finish.is_none() {
452	            error = Some(format!("OpenAIError: missing finish_reason for choice {idx}"));
453	        }
454	        if error.is_none() && ch.role.is_none() {
455	            error = Some(format!("OpenAIError: missing role for choice {idx}"));
456	        }
457	        for t in ch.tools.values() {
458	            let custom = t.ty.as_ref().and_then(Value::as_str) == Some("custom");
459	            if error.is_none() && t.ty.is_none() {
460	                error = Some("OpenAIError: missing tool_calls[].type".into());
461	            }
462	            let (kind, body) = if custom { ("custom", &t.custom) } else { ("function", &t.function) };
463	            match body {
464	                Some((name, arguments)) => calls.push(ModelCall {
465	                    choice,
466	                    kind,
467	                    name: js_string(name),
468	                    arguments: arguments.clone(),
469	                    parsed: false,
470	                }),
471	                None if error.is_none() => error = Some(format!("OpenAIError: missing tool_calls[].{kind}.name")),
472	                None => {}
473	            }
474	        }
475	        if let Some(fc) = &ch.function_call {
476	            if error.is_none() && (fc.get("arguments").is_none_or(Value::is_null) || !js_truthy(fc.get("name"))) {
477	                error = Some("OpenAIError: missing function_call.name or .arguments".into());
478	            }
479	            calls.push(ModelCall {
480	                choice,
481	                kind: "legacy",
482	                name: fc.get("name").map(js_string).unwrap_or_default(),
483	                arguments: fc.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default(),
484	                parsed: false,
485	            });
486	        }
487	    }
488	    Run { calls, error }
489	}
